const fs=require('fs');
const faixas={bronze:[1,30],prata:[31,70],ouro:[71,100],diamante:[101,150]};
const med=JSON.parse(fs.readFileSync('data/catalogo/medalhas.json','utf8'));
const pre=JSON.parse(fs.readFileSync('data/catalogo/premios-participacao.json','utf8'));
const con=JSON.parse(fs.readFileSync('data/catalogo/conquistas.json','utf8'));
const codsMed=new Set(med.itens.map(i=>i.codigo));
const codsPre=new Set(pre.itens.map(i=>i.codigo));
let erros=[];
const cods=new Set();
con.itens.forEach(i=>{
  if(cods.has(i.codigo)) erros.push(i.codigo+' duplicado'); cods.add(i.codigo);
  const fx=faixas[i.tier];
  if(!fx) erros.push(i.codigo+' tier invalido');
  else if(i.pontos<fx[0]||i.pontos>fx[1]) erros.push(i.codigo+' pontos '+i.pontos+' fora de '+i.tier);
  if(!['bimestre','semestre','ano','curso'].includes(i.periodo)) erros.push(i.codigo+' periodo invalido');
  if(!['porFato','fechamentoDePeriodo'].includes(i.gatilho)) erros.push(i.codigo+' gatilho invalido');
  const r=i.regra;
  if(!['contagem','contagemDistinta'].includes(r.forma)) erros.push(i.codigo+' forma invalida');
  if(!['medalha','premioParticipacao','ambos'].includes(r.fonte)) erros.push(i.codigo+' fonte invalida');
  if(r.forma==='contagem' && r.agruparPor!==null) erros.push(i.codigo+' contagem com agruparPor');
  if(r.forma==='contagemDistinta' && !['materia','bimestre','tipoDeEvento'].includes(r.agruparPor)) erros.push(i.codigo+' agruparPor invalido');
  if(r.alvo==='todasAsMatriculasDoPeriodo' && r.agruparPor!=='materia') erros.push(i.codigo+' alvo dinamico sem agruparPor materia');
  if(typeof r.alvo==='number' && r.alvo<2) erros.push(i.codigo+' alvo baixo');
  if(r.agruparPor==='tipoDeEvento' && r.fonte!=='premioParticipacao') erros.push(i.codigo+' tipoDeEvento exige fonte premioParticipacao');
  if(r.agruparPor==='bimestre' && r.fonte!=='medalha') erros.push(i.codigo+' agrupar por bimestre exige medalha');
  if(r.filtroItens){
    r.filtroItens.forEach(c=>{
      const ok = r.fonte==='medalha'? codsMed.has(c) : r.fonte==='premioParticipacao'? codsPre.has(c) : (codsMed.has(c)||codsPre.has(c));
      if(!ok) erros.push(i.codigo+' filtro referencia item inexistente na fonte: '+c);
    });
  }
  if(i.gatilho==='fechamentoDePeriodo' && r.alvo!=='todasAsMatriculasDoPeriodo' && r.forma!=='contagemDistinta') erros.push(i.codigo+' fechamento sem alvo que exija fechamento');
});
console.log('conquistas: '+con.itens.length+' itens');
const porTier={}, porPeriodo={}, porForma={}, porGatilho={};
con.itens.forEach(i=>{porTier[i.tier]=(porTier[i.tier]||0)+1;porPeriodo[i.periodo]=(porPeriodo[i.periodo]||0)+1;porForma[i.regra.forma]=(porForma[i.regra.forma]||0)+1;porGatilho[i.gatilho]=(porGatilho[i.gatilho]||0)+1;});
console.log('  tier:    ',JSON.stringify(porTier));
console.log('  periodo: ',JSON.stringify(porPeriodo));
console.log('  forma:   ',JSON.stringify(porForma));
console.log('  gatilho: ',JSON.stringify(porGatilho));
console.log('  total do catalogo: '+(med.itens.length+pre.itens.length+con.itens.length)+' itens');
console.log('');
console.log(erros.length? 'ERROS:\n'+erros.join('\n') : 'sem erros: faixas, periodos, gatilhos, formas e referencias de filtro coerentes');
"

