const tetoSem=med.filter(i=>i.periodoDeReferencia==='semestre').reduce((s,i)=>s+i.pontos*i.limitePorPeriodo,0);
const medAno=tetoBim*M*bimPorAno + tetoSem*M*semPorAno;
const inst={bimestre:bimPorAno,semestre:semPorAno,ano:1,curso:0};
let conAno=0; const det=[];
con.forEach(i=>{const n=inst[i.periodo]; if(n>0){conAno+=i.pontos*n; det.push(i.codigo+' '+i.pontos+'x'+n);}});
const curso=con.filter(i=>i.periodo==='curso').reduce((s,i)=>s+i.pontos,0);
