const presMed=med.filter(i=>i.base==='presenca').reduce((s,i)=>s+i.pontos*i.limitePorPeriodo*(i.periodoDeReferencia==='bimestre'?bimPorAno:semPorAno),0)*M;
const notaCon=['C02','C04','C08','C11','C14'].reduce((s,c)=>{const i=con.find(x=>x.codigo===c);return s+i.pontos*inst[i.periodo];},0);
const presCon=['C03','C10','C15'].reduce((s,c)=>{const i=con.find(x=>x.codigo===c);return s+i.pontos*inst[i.periodo];},0);
console.log('  nota:     '+notaMed+' em medalhas + '+notaCon+' em conquistas = '+(notaMed+notaCon));
console.log('  presenca: '+presMed+' em medalhas + '+presCon+' em conquistas = '+(presMed+presCon));
console.log('');
console.log('Conquistas de curso, uma vez na vida: '+curso+' (C16+C17+C18)');
"

